/**
 * What `search-input.tsx` (native) and `search-input.web.tsx` share. Its own module because Metro
 * resolves `./search-input` to the web file on web.
 */

import { useEffect, useRef } from "react";

/** The props a search box adds to the input it is. The rest are `Input`'s, on each half. */
export type SearchInputOwnProps = {
  /**
   * The accessible name. A search box usually has no visible label, and an unnamed one is read as
   * "search field" and nothing else. `aria-label` wins over it, and a box pointed at by
   * `aria-labelledby` or an `id` (a `<label htmlFor>`, a `FormField`) takes its name from there
   * unless `label` is passed as well.
   */
  label?: string | undefined;
  /** The clear button's name. Announced, since the ✕ alone says nothing. */
  clearLabel?: string | undefined;
  /**
   * Off, there is no clear button. On, it shows only while there is text to clear, so an empty
   * box is not a box with a dead control in it.
   */
  clearable?: boolean | undefined;
  /**
   * The text once typing has paused: what a search that asks a server sends. Called `debounce`
   * milliseconds after the last key, and at once when the box is emptied or Enter is pressed.
   * `onChangeText` still hears every key, so the box itself never lags.
   */
  onSettledText?: ((text: string) => void) | undefined;
  /** How long typing has to pause before `onSettledText`, in milliseconds. */
  debounce?: number | undefined;
};

/**
 * Hides the ✕ WebKit and Blink draw in a `type="search"` box, so the one clear button is the named
 * one. The web half's alone: react-native-web's reset already hides it, and a device has none.
 */
export const SEARCH_INPUT_CLASS = "[&::-webkit-search-cancel-button]:appearance-none";

/** Long enough that a word is typed in one go, short enough that the answer does not feel late. */
export const SEARCH_DEBOUNCE_MS = 250;

/**
 * The timer behind `onSettledText`, which both halves hold the same way: `later` restarts the
 * wait, `now` ends it. Three apps wrote this beside their search box (#230), each as its own
 * `useEffect` and `setTimeout`.
 */
export function useSettledText(
  onSettledText: ((text: string) => void) | undefined,
  debounce: number,
): { later: (text: string) => void; now: (text: string) => void } {
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  // The handler as of the last render, so a wait that outlives a render calls the current one.
  const handler = useRef(onSettledText);
  useEffect(() => {
    handler.current = onSettledText;
  });
  useEffect(() => () => clearTimeout(timer.current), []);

  const now = (text: string) => {
    clearTimeout(timer.current);
    handler.current?.(text);
  };
  const later = (text: string) => {
    clearTimeout(timer.current);
    if (onSettledText === undefined) {
      return;
    }
    timer.current = setTimeout(() => handler.current?.(text), debounce);
  };
  return { later, now };
}

export const SEARCH_LABEL = "Search";
export const SEARCH_CLEAR_LABEL = "Clear search";

/**
 * The name to put in `aria-label`, or none. `label` is a default only where nothing else names the
 * box, because `aria-label` outranks a `<label htmlFor>` — a "Search" there would silently replace
 * the visible label a `FormField` drew.
 */
export function searchInputName({
  label,
  ariaLabel,
  ariaLabelledBy,
  id,
}: {
  label: string | undefined;
  ariaLabel: string | undefined;
  ariaLabelledBy: string | undefined;
  id: string | undefined;
}): string | undefined {
  if (ariaLabel !== undefined) {
    return ariaLabel;
  }
  if (label !== undefined) {
    return label;
  }
  return ariaLabelledBy || id ? undefined : SEARCH_LABEL;
}

/**
 * A search box: `Input` with a `Search` icon at its start, `type="search"`, a name, and a ✕ that
 * clears it. `search-input.web.tsx` is the web counterpart and `search-input-base.ts` holds what
 * they share.
 *
 * Thirteen search boxes across eight projects are this written by hand — a `relative` wrapper, an
 * absolute glyph, a `pl-8` — and most of them have no accessible name beyond a placeholder and no
 * way to clear but backspace. This is those, with the three details in the box:
 *
 * - **It is a search field.** `type="search"` raises the search keyboard on device and, through
 *   `Input`, is `role="searchbox"`, so a screen reader says what the box is for.
 * - **It is named.** `label`, default "Search", unless something else already names it.
 * - **The ✕ shows only with text in the box,** is a named button, and puts focus back in the
 *   field, so clearing and typing again is one motion.
 *
 * The text is `onChangeText`, as on every native input. The box keeps its own copy only when the
 * caller does not hold `value`, which is what lets the ✕ clear an uncontrolled box and still know
 * when to show itself.
 */
import { useImperativeHandle, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Search, X } from "@/components/ui/icons";
import { Input, type InputHandle, type InputProps } from "@/components/ui/input";
import {
  SEARCH_CLEAR_LABEL,
  SEARCH_DEBOUNCE_MS,
  type SearchInputOwnProps,
  searchInputName,
  useSettledText,
} from "@/components/ui/search-input-base";

export type SearchInputProps = Omit<InputProps, "type" | "leadingSlot" | "trailingSlot"> &
  SearchInputOwnProps;

export function SearchInput({
  label,
  clearLabel = SEARCH_CLEAR_LABEL,
  clearable = true,
  value,
  defaultValue,
  onChangeText,
  onSettledText,
  debounce = SEARCH_DEBOUNCE_MS,
  onSubmitEditing,
  disabled,
  id,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ref,
  ...props
}: SearchInputProps) {
  const [draft, setDraft] = useState(defaultValue ?? "");
  const text = value ?? draft;
  const inner = useRef<InputHandle>(null);
  useImperativeHandle<InputHandle, InputHandle>(ref, () => ({
    focus: () => inner.current?.focus(),
  }));

  const settled = useSettledText(onSettledText, debounce);

  const change = (next: string) => {
    if (value === undefined) {
      setDraft(next);
    }
    onChangeText?.(next);
    // An emptied box is not someone part-way through a word, so there is nothing to wait for.
    if (next === "") {
      settled.now(next);
    } else {
      settled.later(next);
    }
  };

  // Enter asks now. Left as the caller's own when nothing is settling, so the key is not taken
  // from a form that submits on it.
  const submit = onSettledText
    ? () => {
        settled.now(text);
        onSubmitEditing?.();
      }
    : onSubmitEditing;

  return (
    <Input
      {...props}
      ref={inner}
      type="search"
      value={text}
      onChangeText={change}
      onSubmitEditing={submit}
      disabled={disabled}
      id={id}
      aria-label={searchInputName({ label, ariaLabel, ariaLabelledBy, id })}
      aria-labelledby={ariaLabelledBy}
      leadingSlot={<Search />}
      trailingSlot={
        clearable && text !== "" && disabled !== true ? (
          <Button
            variant="secondary"
            size="icon-xs"
            aria-label={clearLabel}
            onPress={() => {
              change("");
              inner.current?.focus();
            }}
            iconSlot={<X />}
          />
        ) : undefined
      }
    />
  );
}

/**
 * The web search box — see `search-input.tsx` for what it is and why, and `search-input-base.ts`
 * for what the halves share.
 *
 * It takes what the web `Input` takes, so both change handlers work: `onChangeText` hands over the
 * text, as on native, and `onChange` the DOM event, as on a shadcn input. The ✕ has to reach both,
 * and it has no event to hand `onChange`, so it makes one: it writes the empty value through the
 * element's own setter and dispatches `input`, which React reads as the user clearing the box and
 * `Input` turns into both calls. That also clears an uncontrolled box, which is why this half never
 * holds the text — only whether there is any, for the ✕.
 *
 * The ✕ is a plain `<button>` wearing `buttonVariants`, not `Button`, for the reason
 * `file-picker.web.tsx` gives: this file is also what an Expo web app runs, where `Button` is a
 * `Pressable` that takes `onPress`, while the compiled one takes `onClick`. A `<button>` is the same
 * element in both. For the same reason the body touches only what both `Input` halves type —
 * `onChange` passes through untouched rather than being read here.
 */
import { useCallback, useRef, useState } from "react";
import { buttonVariants } from "@/components/ui/button";
import { Search, X } from "@/components/ui/icons";
import { Input, type InputHandle, type InputProps } from "@/components/ui/input";
import {
  SEARCH_CLEAR_LABEL,
  SEARCH_DEBOUNCE_MS,
  SEARCH_INPUT_CLASS,
  type SearchInputOwnProps,
  searchInputName,
  useSettledText,
} from "@/components/ui/search-input-base";
import { cn } from "@/lib/utils";

export type SearchInputProps = Omit<InputProps, "type" | "leadingSlot" | "trailingSlot"> &
  SearchInputOwnProps;

export function SearchInput({
  label,
  clearLabel = SEARCH_CLEAR_LABEL,
  clearable = true,
  value,
  defaultValue,
  onChangeText,
  onSettledText,
  debounce = SEARCH_DEBOUNCE_MS,
  onSubmitEditing,
  disabled,
  id,
  className,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ref,
  ...props
}: SearchInputProps) {
  const element = useRef<HTMLInputElement | null>(null);
  const [typed, setTyped] = useState(String(defaultValue ?? "") !== "");
  const filled = value === undefined ? typed : String(value) !== "";

  // The ref `Input` hands back is the `<input>` on the web; the caller's ref gets it too.
  const attach = useCallback(
    (node: InputHandle | null) => {
      element.current = node as HTMLInputElement | null;
      // The node is both: an `HTMLInputElement` has `focus` and `select`.
      if (typeof ref === "function") {
        (ref as (node: InputHandle | null) => void)(node);
      } else if (ref) {
        (ref as { current: InputHandle | null }).current = node;
      }
    },
    [ref],
  );

  const settled = useSettledText(onSettledText, debounce);

  // Enter asks now. Left as the caller's own when nothing is settling: `Input` holds Enter back
  // from the browser once it has a handler, and a form that submits on it has to keep the key.
  const submit = onSettledText
    ? () => {
        settled.now(element.current?.value ?? "");
        onSubmitEditing?.();
      }
    : onSubmitEditing;

  const clear = () => {
    const box = element.current;
    if (!box) {
      return;
    }
    // The prototype's setter, not `box.value = ""`: React tracks the last value it saw on the
    // element, and a plain assignment updates that too, so the `input` event would read as no
    // change and `onChange` would never fire.
    Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")?.set?.call(box, "");
    box.dispatchEvent(new Event("input", { bubbles: true }));
    box.focus();
  };

  return (
    <Input
      {...props}
      ref={attach}
      type="search"
      value={value}
      defaultValue={defaultValue}
      onChangeText={(text) => {
        setTyped(text !== "");
        onChangeText?.(text);
        // An emptied box is not someone part-way through a word, so there is nothing to wait for.
        if (text === "") {
          settled.now(text);
        } else {
          settled.later(text);
        }
      }}
      onSubmitEditing={submit}
      disabled={disabled}
      id={id}
      aria-label={searchInputName({ label, ariaLabel, ariaLabelledBy, id })}
      aria-labelledby={ariaLabelledBy}
      className={cn(SEARCH_INPUT_CLASS, className)}
      leadingSlot={<Search />}
      trailingSlot={
        clearable && filled && disabled !== true ? (
          <button
            type="button"
            data-slot="search-input-clear"
            aria-label={clearLabel}
            onClick={clear}
            className={buttonVariants({ variant: "secondary", size: "icon-xs" })}
          >
            <X />
          </button>
        ) : undefined
      }
    />
  );
}
